import unreal
MEL=unreal.MaterialEditingLibrary;EAL=unreal.EditorAssetLibrary;AT=unreal.AssetToolsHelpers.get_asset_tools()
p='/Game/NK/Mat/M_Stripe'
if EAL.does_asset_exist(p): EAL.delete_asset(p)
m=AT.create_asset('M_Stripe','/Game/NK/Mat',unreal.Material,unreal.MaterialFactoryNew()); m.set_editor_property('two_sided',True)
E=lambda c,x,y: MEL.create_material_expression(m,c,x,y)
uv=E(unreal.MaterialExpressionTextureCoordinate,-900,0)
mu=E(unreal.MaterialExpressionComponentMask,-700,-60); mu.set_editor_property('r',True); mu.set_editor_property('g',False); MEL.connect_material_expressions(uv,'',mu,'')
mv=E(unreal.MaterialExpressionComponentMask,-700,60); mv.set_editor_property('r',False); mv.set_editor_property('g',True); MEL.connect_material_expressions(uv,'',mv,'')
ax=E(unreal.MaterialExpressionScalarParameter,-700,180); ax.set_editor_property('parameter_name','UseV'); ax.set_editor_property('default_value',1.0)
sel=E(unreal.MaterialExpressionLinearInterpolate,-500,0); MEL.connect_material_expressions(mu,'',sel,'A'); MEL.connect_material_expressions(mv,'',sel,'B'); MEL.connect_material_expressions(ax,'',sel,'Alpha')
per=E(unreal.MaterialExpressionScalarParameter,-500,180); per.set_editor_property('parameter_name','Period'); per.set_editor_property('default_value',12.0)
dv=E(unreal.MaterialExpressionDivide,-300,0); MEL.connect_material_expressions(sel,'',dv,'A'); MEL.connect_material_expressions(per,'',dv,'B')
fr=E(unreal.MaterialExpressionFrac,-150,0); MEL.connect_material_expressions(dv,'',fr,'')
st=E(unreal.MaterialExpressionStep,0,0); st.set_editor_property('const_y',0.5); MEL.connect_material_expressions(fr,'',st,'X')
ca=E(unreal.MaterialExpressionVectorParameter,0,-250); ca.set_editor_property('parameter_name','ColA'); ca.set_editor_property('default_value',unreal.LinearColor(0.7,0.02,0.03,1))
cb=E(unreal.MaterialExpressionVectorParameter,0,200); cb.set_editor_property('parameter_name','ColB'); cb.set_editor_property('default_value',unreal.LinearColor(0.85,0.85,0.85,1))
le=E(unreal.MaterialExpressionLinearInterpolate,250,0); MEL.connect_material_expressions(ca,'',le,'A'); MEL.connect_material_expressions(cb,'',le,'B'); MEL.connect_material_expressions(st,'',le,'Alpha')
MEL.connect_material_property(le,'',unreal.MaterialProperty.MP_BASE_COLOR)
ro=E(unreal.MaterialExpressionConstant,250,200); ro.set_editor_property('r',0.5); MEL.connect_material_property(ro,'',unreal.MaterialProperty.MP_ROUGHNESS)
MEL.recompile_material(m); EAL.save_loaded_asset(m)
open(r'C:\Users\Antoine\Documents\NewKarterz_3D\stripe_ok.txt','w').write('ok')
